-- --------------------------------------------------------
-- Table structure for table `boss_config`
-- --------------------------------------------------------

CREATE TABLE `boss_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `boss_id` int NOT NULL COMMENT 'ID boss (âm), khớp với BossID.java',
  `boss_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `gender` tinyint NOT NULL DEFAULT '0' COMMENT '0=TraiDat, 1=Namec, 2=Xayda',
  `outfit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0,0,0,-1,-1,-1' COMMENT 'head,body,leg,bag,aura,eff',
  `dame` bigint NOT NULL DEFAULT '0',
  `hp` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1000' COMMENT 'CSV cho multi-level hp',
  `map_join` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'CSV map IDs',
  `skill_temp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'JSON [[skillId,level,chance],...]',
  `text_s` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'JSON array chat khi xuất hiện',
  `text_m` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'JSON array chat trong trận',
  `text_e` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'JSON array chat khi chết',
  `seconds_rest` int NOT NULL DEFAULT '600' COMMENT 'Giây nghỉ sau khi chết',
  `appear_type` int NOT NULL DEFAULT '0' COMMENT '0=default,1=appear_with_another,2=another_level,3=call_by_another',
  `bosses_appear_together` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'CSV boss_id các đệ tử',
  `level_index` int NOT NULL DEFAULT '0' COMMENT 'Chỉ số level (0=dạng đầu)',
  `boss_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DEFAULT',
  `is_notify_disabled` tinyint(1) NOT NULL DEFAULT '0',
  `is_zone01_spawn_disabled` tinyint(1) NOT NULL DEFAULT '0',
  `spawn_count` int NOT NULL DEFAULT '1',
  `max_damage_per_hit` bigint DEFAULT NULL,
  `damage_divisor` int DEFAULT NULL,
  `damage_flat_reduction` bigint DEFAULT NULL,
  `dodge_rate` int DEFAULT NULL,
  `pierce_reverse` tinyint(1) NOT NULL DEFAULT '0',
  `auto_leave_timeout` bigint DEFAULT NULL,
  `auto_leave_reset_on_player` tinyint(1) NOT NULL DEFAULT '0',
  `auto_leave_random_min` bigint DEFAULT NULL,
  `auto_leave_random_max` bigint DEFAULT NULL,
  `append_random_name` tinyint(1) NOT NULL DEFAULT '0',
  `done_chat_s_to_afk` tinyint(1) NOT NULL DEFAULT '0',
  `skip_notify_at_level` int DEFAULT NULL,
  `skip_move_at_level` int DEFAULT NULL,
  `special_abilities` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `reward_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `custom_class` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Fully-qualified Java class, NULL = GenericBoss',
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_boss_id` (`boss_id`),
  KEY `idx_boss_id_level` (`boss_id`, `level_index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Cấu hình boss load từ DB';

