(-22,'Rambo',2,'162,163,164,-1,-1,-1',12400,'20000000','74,75,76,77','[[1,7,10000],[1,1,1000]]',NULL,'["|-1|HAHAHA","|-1|Tao chỉ cần 10 giây để giết hết bọn mày","|-1|Thấy ta đẹp trai không","|-1|Mày sợ tao chưa","|-1|Ta sẽ tàn sát khu này trong vòng 5 phút nữa","|-1|Tao sẽ giết hết bọn mày"]','["|-1|Ôi bạn ơi..."]',600,0,NULL,0,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":1, "pointBHM":1, "drops":[{"itemId":17, "chance":50}, {"itemId":14, "chance":10}]}','boss.boss_manifest.Nappa.Rambo');
