(-28,'Fide đại ca 2',2,'186,187,188,-1,-1,-1',50000,'100000000','80','[[5,1],[5,2],[5,3],[5,4],[5,5],[5,6],[5,7],[17,1],[17,2],[17,3],[17,4],[17,5],[17,6],[17,7]]','["|-1|Hê hê, cẩn thận đi","|-1|Nếu đã biến thành thế này thì ta sẽ không nhùn nhặn như trước đâu"]','["|-1|Oải rồi hả?","|-1|Ê cố lên nhóc","|-1|Ôi, xin lỗi nhé. Sức mạnh lớn quá nên ta cũng chẳng điều khiển nổi nữa!","|-1|Hahaha! Ấn tượng đấy! Tên nào cũng lủi rất nhanh!","|-2|A...Tốc độ nhanh quá!","|-1|Hình như... mày không phải là một thằng nhóc bình thường!"]','["|-1|Ác quỷ biến hình, Graaaaa...."]',0,2,NULL,1,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":3, "pointBHM":1}','boss.boss_manifest.Frieza.Fide'),
(-28,'Fide đại ca 3',2,'189,190,191,-1,-1,-1',122000,'150000000','80','[[3,1],[3,2],[3,3],[3,4],[3,5],[3,6],[3,7],[17,1],[17,2],[17,3],[17,4],[17,5],[17,6],[17,7]]','["|-1|Ta sẽ cho các ngươi thấy đâu mới là sức mạnh của ta!!"]','["|-1|Ta nói các ngươi rồi! Sức mạnh này của ta còn đáng sợ hơn địa ngục!!","|-1|Ta chơi thêm chút nữa chắc ngươi chóng mặt buồn nôn mất!!","|-2|Ăn gì mà khỏe thế!","|-2|Chết đi Fide!!!!","|-1|Hô hô hô hô","|-1|Chán thật! Khí của ngươi sắp hết rồi. Để ta tiễn ngươi về địa ngục!","|-1|Ngươi quá tự cao rồi đấy,xem ta đây!"]','["|-1|Lũ khốn..","|-1|..Một ngày nào đó ta sẽ quay lại và trả thù các ngươi","|-1|Nhớ mặt tao đấy !"]',0,2,NULL,2,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":10, "pointBHM":10, "dropDoTL":{"chance":30}}','boss.boss_manifest.Frieza.Fide');
