INSERT INTO `boss_config` (`boss_id`,`boss_name`,`gender`,`outfit`,`dame`,`hp`,`map_join`,`skill_temp`,`text_s`,`text_m`,`text_e`,`seconds_rest`,`appear_type`,`bosses_appear_together`,`level_index`,`boss_type`,`is_notify_disabled`,`is_zone01_spawn_disabled`,`spawn_count`,`special_abilities`,`reward_config`,`custom_class`) VALUES
(-31,'Dr.Kôrê',0,'255,256,257,-1,-1,-1',12000,'150000000','96,94,93','[[22,3,10000],[1,7,10000],[17,7,1000]]','["|-2|Chào anh! em đứng đây từ chiều","|-1|Quái lạ! Sao chúng biết rõ tung tích của bọn ta thế nhỉ?","|-1|Chúng còn biết chính xác ta sẽ xuất hiện ở đây để đón đánh nữa!","|-1|Chúng mày là ai từ đâu tới?Cho tao xin cái địa chỉ","|-2|Điều ấy biết hay không cũng không còn quan trọng nữa","|-1|Ừ bọn bây chỉ là hạng tôm tép ta chẳng cần biết tên làm gì!","|-1|Số 19! Xuất chiêu đi nào","|0|Okê đại ca, em sẽ xử lý bọn này trong vòng 2 tiếng."]','["|-1|Oải rồi hả?","|-1|Ê cố lên nhóc","|-1|Chán","|-1|Mi khá đấy, nhưng so với ta cũng chỉ là hạng tôm tép","|-1|Lôi Công Trảo","|-1|Cho dù ngươi có mạnh đến đâu.. thì cũng không đánh bại được rôbốt bọn ta","|-2|Lão già khôn thật!!","|-2|Hừ! Lão già khốn kiếp!"]',NULL,600,0,'-30',0,'DEFAULT',0,0,1,'{"absorbSkillIds": [1, 3, 5], "absorbRate": 1.0}','{"checkTask":true, "pointBossDay":7, "pointBHM":5, "drops":[{"itemId":457, "chance":80, "count":[1,2]}]}','boss.boss_manifest.Android.DrKore'),
(-30,'Android 19',0,'249,250,251,-1,-1,-1',12200,'180000000','96,94,93','[[1,7,1000],[17,7,10000]]',NULL,'["|-1|Oải rồi hả?","|-1|Ê cố lên nhóc","|-1|Chán","|-1|Ngươi sẽ không bao giờ thắng được đâu!!","|-2|Ngươi vừa hút được nhiều rồi đấy, nhưng giờ thì đừng hòng!!"]',NULL,0,1,NULL,0,'DEFAULT',0,0,1,'{"absorbSkillIds": [1, 3, 5], "absorbRate": 1.0}','{"checkTask":true, "pointBossDay":7, "pointBHM":5, "drops":[{"itemId":457, "chance":80, "count":[1,2]}]}','boss.boss_manifest.Android.Android19'),
(-33,'Android 14',0,'246,247,248,-1,-1,-1',12000,'225000000','104','[[1,7,10000],[17,7,1000]]','["|-2|Các ngươi là ai?","|-2|Ta không thể cảm nhận được khí của các ngươi, các ngươi không phải là con người đúng chứ?","|-2|Ta hiểu rồi, các ngươi là rôbốt sát thủ do tiến sĩ Kôrê tạo ra chứ gì?"]',NULL,'["|0|Số 14 và số 15 tiêu tùng cả rồi à?"]',600,0,'-32,-34',0,'DEFAULT',0,0,1,'{"undyingWhileOthersAlive": [-32, -33, -34]}','{"checkTask":true, "pointBossDay":7, "pointBHM":5, "drops":[{"itemId":457, "chance":80, "count":[1,2]}]}','boss.boss_manifest.Android.Android14'),
(-32,'Android 13',0,'252,253,254,-1,-1,-1',12055,'200000000','104','[[1,7,10000],[17,7,1000]]','["|-1|Sôn..gôku","|-2|Lại là tiến sĩ Kôrê à.. rốt cuộc ông ta đã tạo ra bao nhiêu rôbốt nhân tạo thế nhỉ?","|-1|Bọn ta là rôbốt sát thủ, sinh ra từ máy tính ngài Kôrê,..","|-1|..cho một mục tiêu duy nhất là giết Sôngôku!","|-1|Mong muốn trả thù Gôku của ngài Kôrê đã được lưu hết vào máy tính..","|-1|Mục tiêu của bọn ta chỉ là Gôku, nhưng mà.. nếu ngươi mà cản đường thì là chuyện khác!"]','["|-1|Sao thế hả? Ta mới chỉ khởi động thôi mà!","|-2|Ngươi đánh giá thấp bọn ta quá đấy!","|-2|Đừng có tưởng bở, lũ sâu bọ!","|-1|Nếu có ý định gây trở ngại cho cuộc chiến giữa ta và Sôngôku, thì ta cũng sẽ giết ngươi ngay lập tức"]','["|-1|Sô..Sông...gôku....."]',0,3,NULL,0,'DEFAULT',0,0,1,'{"undyingWhileOthersAlive": [-32, -33, -34]}','{"checkTask":true, "pointBossDay":7, "pointBHM":5, "drops":[{"itemId":457, "chance":80, "count":[1,2]}]}','boss.boss_manifest.Android.Android13'),
(-34,'Android 15',0,'261,262,263,-1,-1,-1',19200,'250000000','104','[[1,7,10000],[17,7,1000]]',NULL,NULL,'["|-2|Thì ra vẫn chỉ là một đống sắt vụn!"]',0,1,NULL,0,'DEFAULT',0,0,1,'{"undyingWhileOthersAlive": [-32, -33, -34]}','{"checkTask":true, "pointBossDay":7, "pointBHM":5, "drops":[{"itemId":457, "chance":80, "count":[1,2]}]}','boss.boss_manifest.Android.Android15');
INSERT INTO `boss_config` (`boss_id`,`boss_name`,`gender`,`outfit`,`dame`,`hp`,`map_join`,`skill_temp`,`text_s`,`text_m`,`text_e`,`seconds_rest`,`appear_type`,`bosses_appear_together`,`level_index`,`boss_type`,`is_notify_disabled`,`is_zone01_spawn_disabled`,`spawn_count`,`special_abilities`,`reward_config`,`custom_class`) VALUES
(-35,'Pic',0,'237,238,239,-1,-1,-1',17022,'280000000','97,98,99','[[4,1],[4,2],[4,3],[4,4],[4,5],[4,6],[4,7],[1,1],[1,2],[1,3],[1,4],[1,5],[1,6],[1,7]]','["|-1|Chào! Có Gôku ở đây không?","|-3|Tôi không nghĩ Gôku ở đây đâu!","|-2|Biến khỏi đây đi, Gôku không có ở đây đâu!","|-1|Bọn ta cũng nghĩ vậy, ngươi nói cho bọn ta biết hắn ở đâu được không!?","|-2|Ngươi nghĩ bọn ta sẽ nói sao??","|-1|Nếu ngươi không chịu nói bọn ta sẽ phải ra tay.."]','["|-1|Ngươi thực sự rất mạnh dù không phải là một rôbốt. Ngươi không phải là Piccôlô","|-1|Nhưng ta không quan tâm ngươi là ai, ta chỉ cần biết Gôku đang ở đâu!","|-1|Sao ngươi không chịu nói cho ta biết chứ!?","|-1|Vậy thì ta bắt buộc phải tiếp tục đánh buộc ngươi phải nói ra!","|-1|Lần này ta không nương tay đâu!","|1|Hắn thực sự rất mạnh, đúng là cuộc chiến cân sức"]','["|1|Pic tiêu rồi, tớ lên trước nhé!","|-3|Okê, xin cứ tự nhiên"]',0,1,NULL,0,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":5, "pointBHM":5}','boss.boss_manifest.Android.Pic'),
(-36,'Poc',0,'240,241,242,-1,-1,-1',18000,'300000000','97,98,99','[[1,1],[1,2],[1,3],[1,4],[1,5],[1,6],[1,7]]',NULL,'["|-1|Đừng tưởng ta đây là con gái mà dễ bắt nạt nhé","|-1|Khôn hồn thì chỉ chỗ Gôku cho bọn ta nhanh đi","|-3|Coi kìa, một lũ xúm lại bắt nạt một cô gái kìa..","|-1|Đừng có mà trọng nam khinh nữ","|-2|Tại sao cô gái xinh đẹp thế này mà lại là rôbốt nhỉ?"]','["|-2|Cô gái xinh đẹp vậy mà lại bị tên tiến sĩ Kôrê biến thành người máy.."]',0,1,NULL,0,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":5, "pointBHM":5}','boss.boss_manifest.Android.Poc'),
(-37,'King Kong',0,'243,244,245,-1,-1,-1',12000,'350000000','97,98,99','[[17,1],[17,2],[17,3],[17,4],[17,5],[17,6],[17,7],[3,1],[3,2],[3,3],[3,4],[3,5],[3,6],[3,7]]',NULL,'["|-1|Mau đền mạng cho những người bạn của ta","|-1|Sức mạnh của ta chênh nhau với các ngươi một trời một vực đấy!","|-1|Thằng kia đừng để bọn nó trói tao !"]',NULL,600,0,'-35,-36',0,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":5, "pointBHM":5}','boss.boss_manifest.Android.KingKong');
