INSERT INTO `boss_config` (`boss_id`,`boss_name`,`gender`,`outfit`,`dame`,`hp`,`map_join`,`skill_temp`,`text_s`,`text_m`,`text_e`,`seconds_rest`,`appear_type`,`bosses_appear_together`,`level_index`,`boss_type`,`is_notify_disabled`,`is_zone01_spawn_disabled`,`spawn_count`,`special_abilities`,`reward_config`,`custom_class`) VALUES
(-100,'Xên bọ hung',2,'228,229,230,-1,-1,-1',100000,'300000000','100','[[1,7,1000],[1,7,1000],[17,7,10000],[20,7,10000]]','["|-2|Cái gì kia vậy!? Đó là loài gì thế!!?","|-1|Hôm nay sẽ là ngày đáng nhớ đây!","|-1|Ta sẽ hấp thụ số 17 và 18 để đạt được dạng hoàn hảo!","|-1|Sao vậy, Picôlô? Nếu ngươi muốn ngăn ta lại thì xong lên đi chứ!?"]','["|-2|Hắn làm ta bất ngờ đấy! Khốn kiếp!","|-1|Đến đây nào! Khi kết hợp với ta, ngươi sẽ trở nên bất bại, trở thành một thể sống hoàn mỹ!","|-1|Làm đứt đuôi ta ư? Đừng quên ta có tế bào của Picôlô!!","|-1|Ta có thể tái tạo.. mọi bộ phận cơ thể!","|-1|Có vẻ như ta đã trở nên quá mạnh, chắc là ta đã giết nhiều người hơn dự tính!!","|-1|Ngươi không thể thắng nổi ta! Từ bỏ đi!!","|-1|Đến lúc ta hấp thu ngươi rồi","|-1|Hê hê hê, rồi ngươi sẽ trở thành một phần của con quái vật này thôi!"]','["|-2|Khốn kiếp, Pic.. hắn bị Cell hấp thu rồi!!"]',600,0,NULL,0,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":5, "pointBHM":5, "drops":[{"itemId":16, "chance":100}]}','boss.boss_manifest.Cell.XenBoHung'),
(-100,'Xên bọ hung 2',2,'231,232,233,-1,-1,-1',100000,'500000000','100','[[1,7,1000],[1,7,1000],[17,7,10000]]',NULL,'["|-2|Nguy rồi... thực sự nguy to rồi!","|-1|Các ngươi nghĩ có thể chạy được sao!?","|-1|Muốn chạy khỏi ta thì đừng hòng!!","|-1|Ta cũng ngạc nhiên với tốc độ của mình! Đó tất nhiên là do ta hấp thụ được số 17!","|-1|Ta muốn thử xem sức mạnh này đến đâu...","|-1|Đã đến lúc ta đạt đến trạng thái hoàn hảo.!","|-1|Muốn chạy à!!? Ta sẽ không để ngươi thoát đâu!!"]','["|-1|Đến lúc rồi!"]',0,2,NULL,1,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":7, "pointBHM":7}','boss.boss_manifest.Cell.XenBoHung'),
(-100,'Xên hoàn thiện',2,'234,235,236,-1,-1,-1',100000,'800000000','100','[[1,7,1000],[1,7,1000],[20,7,10000],[19,6,100000],[17,7,10000],[22,7,100000]]','["|-2|Cuối cùng hắn cũng đã biến đổi","|-2|Khốn kiếp! Phải kết liễu hắn ngay lúc này!"]','["|-2|Cell đã đạt đến dạng hoàn hảo rồi!","|-1|Xin lỗi.. Ngươi có thể giúp ta làm nóng cơ thể lên không !?","|-2|Tình hình nguy cấp rồi!","|-1|Thì ta đã bảo đây chỉ là làm nóng cơ thể mà!!","|-1|Giờ ngươi chỉ là rác rưởi mà thôi!"]','["|-1|Oái.. không...","|-1|Cơ thể hoàn hảo của ta!!","|-1|Ta không tin chuyện này sẽ xảy ra!!","|-1|Đồ khốn kiếp!! Rồi ngươi sẽ phải trả giá"]',0,2,NULL,2,'DEFAULT',0,0,1,NULL,'{"checkTask":true, "pointBossDay":10, "pointBHM":10, "dropDoTL":{"chance":40}}','boss.boss_manifest.Cell.XenBoHung'),
