(-616,'Xeko',0,'1925,1905,1906,-1,-1,-1',17000,'10000000','1,15,8,42,43,44','[[17,7,1000],[3,7,1000],[22,7,100000]]',NULL,'["|-1|Hehe với trí thông minh của tao, các ngươi không có cửa!","|-1|Tao là Xeko! Thiên tài đây!","|-1|Các ngươi yếu quá!","|-1|Để tao tính toán xem... các ngươi sẽ thua!","|-1|HAHAHAHA"]','["|-1|Không thể nào! Tao mà thua sao?","|-1|Chaien! Trả thù cho tao!","|-1|Đồ khốn kiếp!"]',0,1,NULL,0,'DEFAULT',0,0,1,'{"groupOrder": true}','{"checkTask":true, "pointBossDay":1, "pointBHM":1}','boss.boss_manifest.DoraemonForce.Xeko'),
